import assert from 'node:assert/strict'
import { mkdirSync, rmSync, writeFileSync } from 'node:fs'
import { launch, sleep, js, info, pointer, typeText, browserBack, topbar, screen, network } from './mobile-mode-qa-helpers.mjs'

const BASE='https://osrm.github.io/catfood_web/'
const DEPLOY_SHA=process.env.DEPLOY_SHA
const EXPECTED_CSS=process.env.EXPECTED_CSS
const EXPECTED_JS=process.env.EXPECTED_JS
const OUT='qa-artifacts'
const STORAGE_KEY='catfood.switch-session.v1'
mkdirSync(OUT,{recursive:true})
assert.ok(DEPLOY_SHA&&EXPECTED_CSS&&EXPECTED_JS)

async function liveAssets(){for(let i=0;i<30;i++){const r=await fetch(`${BASE}?mode_qa=${Date.now()}`,{cache:'no-store',headers:{'cache-control':'no-cache'}}),h=await r.text();if(r.ok&&h.includes(EXPECTED_CSS)&&h.includes(EXPECTED_JS))return{status:r.status,css:EXPECTED_CSS,js:EXPECTED_JS};await sleep(1000)}throw new Error('deployed asset mismatch')}

async function homeControls(c){return c.eval(`(()=>{const inspect=n=>{const s=getComputedStyle(n),r=n.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,h=r.width&&r.height&&x>=0&&x<innerWidth&&y>=0&&y<innerHeight?document.elementFromPoint(x,y):null;return{text:n.textContent.replace(/\\s+/g,' ').trim(),rect:[r.left,r.top,r.width,r.height],rendered:s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0,inViewport:r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth,centerHit:Boolean(h&&(h===n||n.contains(h)))}};return{nav:[...document.querySelectorAll('.home-nav button')].map(inspect),paths:[...document.querySelectorAll('.home-start-path button')].map(inspect),search:inspect(document.querySelector('.home-search-console button'))}})()`)}

async function enterHome(c,mode,query='몬지'){
  assert.equal(await screen(c),'home',`not home before ${mode}`)
  if(mode==='explore'){const control=await pointer(c,'button','조건 고르기 →');await c.wait(`document.querySelector('.research-workspace')`,'explore');return{mode,method:'home-button',control}}
  if(mode==='switch'){const control=await pointer(c,'button','현재 사료로 시작하기 →');await c.wait(`document.querySelector('.switch-find-stage,.switch-step-layout,.switch-results-stage')`,'switch');return{mode,method:'home-button',control}}
  await typeText(c,'.home-search-console input',query);const control=await pointer(c,'.home-search-console button','검색');await c.wait(`document.querySelector('.lookup-input')`,'lookup');await c.wait(`document.querySelectorAll('.research-result-card').length>0`,'lookup results');return{mode,method:'home-search',query,control}
}

async function goHome(c){const b=await info(c,'.research-brand');if(b?.rendered&&b.inViewport&&b.centerHit){const control=await pointer(c,'.research-brand');await c.wait(`document.querySelector('.home-shell')`,'home by brand');return{method:'brand',control}}const back=await browserBack(c);await c.wait(`document.querySelector('.home-shell')`,'home by back');return{method:'browser-back',brand:b,back}}

async function routeMode(c,target){const labels={explore:'조건으로 찾기',lookup:'제품 찾기',switch:'현재 사료'},tb=await topbar(c),b=tb.buttons.find(x=>x.text===labels[target]);if(b?.rendered&&b.inViewport&&b.centerHit){const control=await pointer(c,'.mode-nav .mode-button',labels[target]);if(target==='switch')await c.wait(`document.querySelector('.switch-find-stage,.switch-step-layout,.switch-results-stage')`,'switch direct');else if(target==='lookup')await c.wait(`document.querySelector('.lookup-input')`,'lookup direct');else await c.wait(`document.querySelector('.research-workspace')`,'explore direct');return{target,mechanism:'direct-mode-button',topbarBefore:tb,control}}const exit=await goHome(c),entry=await enterHome(c,target);return{target,mechanism:'via-home',topbarBefore:tb,exit,entry}}

async function readSwitch(c){return c.eval(`(()=>{const r=sessionStorage.getItem(${js(STORAGE_KEY)});return r?JSON.parse(r).state:null})()`)}
async function visibleSwitch(c){return c.eval(`({product:document.querySelector('.switch-reference-product strong')?.textContent.trim()||null,sku:document.querySelector('.switch-reference-sku strong')?.textContent.trim()||null,heading:document.querySelector('.switch-step-header h1')?.textContent.trim()||document.querySelector('.switch-find-hero h1')?.textContent.trim()||null,active:[...document.querySelectorAll('.switch-choice.is-active')].map(n=>n.textContent.replace(/\\s+/g,' ').trim())})`)}

async function addCompare(c,index){await pointer(c,'.research-result-card',null,index);await c.wait(`document.querySelector('.research-quick-view')`,'quick view');const name=await c.eval(`document.querySelector('.quick-view-identity h1')?.textContent.trim()`),text=await c.eval(`[...document.querySelectorAll('.quick-view-actions button')].find(b=>b.textContent.includes('비교에 추가'))?.textContent.trim()`);assert.ok(text,`no compare add ${name}`);const add=await pointer(c,'.quick-view-actions button',text),close=await pointer(c,'.quick-view-topline button','닫기 ×');await c.wait(`!document.querySelector('.research-quick-view')`,'quick close');return{name,add,close}}

async function runViewport(width,height){
  const p=`${width}x${height}`,r={width,height,captures:[],homeEntries:[],routes:[],topbars:{},findings:[]},browser=await launch(width,height),c=browser.c
  const shot=async name=>{const f=`${p}-${name}.png`;await c.shot(`${OUT}/${f}`);r.captures.push(f)}
  try{
    r.chrome=browser.version;await c.nav(BASE);await c.wait(`document.querySelector('.home-shell')`,'home');await c.wait(`/\\d/.test(document.querySelector('.home-search-console-copy small')?.textContent||'')`,'catalog');r.fonts=await c.fonts('.home-start h1');assert.ok(r.fonts.some(f=>f.familyName.includes('Noto Sans CJK KR')),'Korean font mismatch');r.homeControls=await homeControls(c);await shot('01-home')

    r.homeEntries.push(await enterHome(c,'explore'));r.topbars.explore=await topbar(c);await shot('02-explore-entry')
    r.routes.push({from:'explore',...(await routeMode(c,'lookup'))});r.topbars.lookup=await topbar(c);await shot('03-lookup-transition')
    r.routes.push({from:'lookup',...(await routeMode(c,'switch'))});r.topbars.switch=await topbar(c);await shot('04-switch-transition')
    r.routes.push({from:'switch',...(await routeMode(c,'explore'))});await shot('05-explore-after-switch')
    await goHome(c);r.homeEntries.push(await enterHome(c,'lookup','몬지'));await shot('06-home-lookup');await goHome(c);r.homeEntries.push(await enterHome(c,'switch'));await shot('07-home-switch')

    await c.wait(`document.querySelector('.switch-find-search input')`,'switch input');await typeText(c,'.switch-find-search input','AATU 연어');await c.wait(`document.querySelectorAll('.switch-find-result').length>0`,'switch results');r.switchSetup={query:'AATU 연어'};r.switchSetup.result=await pointer(c,'.switch-find-result',null,0);r.switchSetup.product=await c.eval(`document.querySelector('.switch-find-result.is-selected strong')?.textContent.trim()`);await c.wait(`[...document.querySelectorAll('button')].some(b=>b.textContent.includes('이 제품을 현재 사료로 선택'))`,'confirm product');r.switchSetup.confirm=await pointer(c,'button','이 제품을 현재 사료로 선택 →');await c.wait(`document.querySelectorAll('.switch-sku-option').length>0`,'sku');r.switchSetup.sku=await pointer(c,'.switch-sku-option',null,0);await c.wait(`document.querySelector('.switch-sku-option.is-selected')`,'sku selected');r.switchSetup.skuText=await c.eval(`document.querySelector('.switch-sku-option.is-selected')?.textContent.replace(/\\s+/g,' ').trim()`);r.switchSetup.next1=await pointer(c,'.switch-step-actions button','다음 →');await c.wait(`document.querySelector('.switch-step-header h1')?.textContent.includes('무엇을 바꾸고 싶나요')`,'change');r.switchSetup.change=await pointer(c,'button.switch-choice','다른 브랜드로 보기');r.switchSetup.next2=await pointer(c,'.switch-step-actions button','다음 →');await c.wait(`document.querySelector('.switch-step-header h1')?.textContent.includes('무엇을 그대로 유지할까요')`,'keep');const keep=await c.eval(`[...document.querySelectorAll('button.switch-choice.wide')].map(b=>b.textContent.replace(/\\s+/g,' ').trim()).find(t=>t.endsWith('유지'))||null`);assert.ok(keep,'no KEEP control');r.switchSetup.keep=await pointer(c,'button.switch-choice.wide',keep);r.switchSetup.keepText=keep;r.switchBefore=await readSwitch(c);r.switchVisibleBefore=await visibleSwitch(c);await shot('08-switch-state-before-exit')
    r.switchExit=await goHome(c);await shot('09-home-after-switch-exit');r.switchReturn=await enterHome(c,'switch');await c.wait(`document.querySelector('.switch-step-header h1')?.textContent.includes('무엇을 그대로 유지할까요')`,'restored keep');r.switchAfter=await readSwitch(c);r.switchVisibleAfter=await visibleSwitch(c);r.switchPreserved=JSON.stringify(r.switchBefore)===JSON.stringify(r.switchAfter);assert.equal(r.switchPreserved,true,'SWITCH state changed');await shot('10-switch-state-after-return')

    await goHome(c);await enterHome(c,'lookup','몬지');await pointer(c,'.research-result-card',null,0);await c.wait(`document.querySelector('.research-quick-view')`,'detail quick');r.detail={product:await c.eval(`document.querySelector('.quick-view-identity h1')?.textContent.trim()`)};r.detail.open=await pointer(c,'.quick-view-actions button','상세 보기 →');await c.wait(`document.querySelector('.detail-stage')`,'detail');r.detail.globalTopbarPresent=await c.eval(`Boolean(document.querySelector('.research-topbar'))`);r.detail.brandPresent=await c.eval(`Boolean(document.querySelector('.research-brand'))`);r.detail.modeNavPresent=await c.eval(`Boolean(document.querySelector('.mode-nav'))`);r.detail.returnControl=await info(c,'.detail-topbar button');await shot('11-detail-entry');r.detail.returnPointer=await pointer(c,'.detail-topbar button','← 돌아가기 · 제품 목록');await c.wait(`document.querySelector('.research-results-list')`,'detail return');await shot('12-detail-return')
    await pointer(c,'.research-result-card',null,0);await c.wait(`document.querySelector('.research-quick-view')`,'detail quick2');await pointer(c,'.quick-view-actions button','상세 보기 →');await c.wait(`document.querySelector('.detail-stage')`,'detail2');r.detail.browserBack=await browserBack(c);await c.wait(`document.querySelector('.research-results-list')`,'detail back');r.detail.afterBack=await screen(c);r.detail.otherModeRoute=await routeMode(c,'explore');r.routes.push({from:'detail-parent',...r.detail.otherModeRoute});await shot('13-detail-parent-to-explore')

    r.routes.push({from:'explore',...(await routeMode(c,'lookup'))});if(!(await c.eval(`document.querySelector('.lookup-input')?.value.trim()`))){await typeText(c,'.lookup-input','몬지')}await c.wait(`document.querySelectorAll('.research-result-card').length>1`,'lookup for compare');r.compare={additions:[await addCompare(c,0),await addCompare(c,1)]};await c.wait(`document.querySelector('.switch-compare-dock')`,'dock');r.compare.open=await pointer(c,'.switch-compare-dock button','비교 보기 →');await c.wait(`document.querySelector('.compare-stage')`,'compare');r.compare.topbar=await topbar(c);r.compare.returnControl=await info(c,'.compare-header button');await shot('14-compare-entry');r.compare.returnPointer=await pointer(c,'.compare-header button','← 제품 목록으로');await c.wait(`document.querySelector('.research-results-list')`,'compare return');await shot('15-compare-return')
    await pointer(c,'.switch-compare-dock button','비교 보기 →');await c.wait(`document.querySelector('.compare-stage')`,'compare2');r.compare.browserBack=await browserBack(c);await c.wait(`document.querySelector('.research-results-list')`,'compare back');r.compare.afterBack=await screen(c);await pointer(c,'.switch-compare-dock button','비교 보기 →');await c.wait(`document.querySelector('.compare-stage')`,'compare3');r.compare.otherModeRoute=await routeMode(c,'explore');r.routes.push({from:'compare',...r.compare.otherModeRoute});await shot('16-compare-to-explore')

    for(const [mode,tb] of Object.entries(r.topbars)){const visible=tb.buttons.filter(b=>b.rendered&&b.inViewport&&b.centerHit).map(b=>b.text);if(!visible.length)r.findings.push({code:'mode-buttons-not-visible',mode,brand:tb.brand});if(tb.active&&!tb.active.rendered)r.findings.push({code:'active-mode-indicator-hidden',mode,active:tb.active.text,headings:tb.headings})}const brandName=r.topbars.explore?.brandAx?.name??null;if(brandName&&!String(brandName).includes('홈'))r.findings.push({code:'brand-accessible-name-does-not-say-home',accessibleName:brandName});if(!r.detail.globalTopbarPresent)r.findings.push({code:'detail-no-global-mode-topbar',returnControl:r.detail.returnControl?.text})
    r.network=await network(c);assert.equal(r.network.sentAnalytics.length,0,'analytics escaped');assert.equal(r.network.sentWrites.length,0,'write escaped');r.status='pass';return r
  }catch(e){r.status='failed';r.error=e instanceof Error?`${e.name}: ${e.message}`:String(e);try{await shot('99-failure')}catch{}throw Object.assign(e instanceof Error?e:new Error(String(e)),{qaResult:r})}finally{c.close();browser.proc.kill('SIGTERM');rmSync(browser.dir,{recursive:true,force:true})}
}

const report={deploySha:DEPLOY_SHA,pagesUrl:BASE,expectedAssets:{css:EXPECTED_CSS,js:EXPECTED_JS},environment:'GitHub-hosted headless Chrome mobile emulation; not a physical device',liveAssets:null,viewports:[],status:'running'}
const save=()=>writeFileSync(`${OUT}/report.json`,JSON.stringify(report,null,2))
try{report.liveAssets=await liveAssets();for(const [w,h] of [[360,844],[390,900]]){try{report.viewports.push(await runViewport(w,h))}catch(e){if(e?.qaResult)report.viewports.push(e.qaResult);throw e}finally{save()}}report.status='pass';save();console.log('MOBILE_MODE_NAVIGATION_QA_PASS',JSON.stringify({deploySha:DEPLOY_SHA,viewports:report.viewports.map(v=>({size:`${v.width}x${v.height}`,routes:v.routes.map(x=>({from:x.from,target:x.target,mechanism:x.mechanism})),findings:v.findings,switchPreserved:v.switchPreserved,detail:{topbar:v.detail?.globalTopbarPresent,brand:v.detail?.brandPresent,modeNav:v.detail?.modeNavPresent,return:v.detail?.returnControl?.text,afterBack:v.detail?.afterBack},compare:{route:v.compare?.otherModeRoute?.mechanism,afterBack:v.compare?.afterBack},network:v.network}))}))}catch(e){report.status='failed';report.error=e instanceof Error?`${e.name}: ${e.message}`:String(e);save();throw e}
